using Suishouyi.Core;
namespace Suishouyi.App;
internal sealed class TrayApplication:ApplicationContext {
 readonly string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Suishouyi");readonly AppSettings settings;readonly NotifyIcon tray;readonly HotKeyService hotkeys;IReadOnlyList<string> models=new[]{"hy3"};string? cli;CancellationTokenSource? request;ResultWindow? result;SettingsWindow? settingsWindow;SetupWindow? setup;IntPtr source;bool busy;Task? activeOperation;TaskStatusWindow? feedback;CaptureOverlay? captureWindow;readonly Control dispatcher=new();readonly EventWaitHandle shutdown=new(false,EventResetMode.AutoReset,"Local\\Suishouyi.Shutdown."+Environment.UserName);RegisteredWaitHandle? shutdownWait;
 readonly Dictionary<TaskMode,Task> operations=new();readonly Dictionary<TaskMode,string> requestModels=new();int revision;
 string SettingsPath=>Path.Combine(data,"settings.json");string Work=>Path.Combine(data,"CLI-work");string Cache=>Path.Combine(data,"models.json");
 public TrayApplication(){Directory.CreateDirectory(data);Directory.CreateDirectory(Work);settings=AppSettings.Load(SettingsPath);dispatcher.CreateControl();shutdownWait=ThreadPool.RegisterWaitForSingleObject(shutdown,(_,_)=>dispatcher.BeginInvoke(ExitThread),null,Timeout.Infinite,false);hotkeys=new((mode,window)=>Start(mode,window));tray=new(){Icon=SystemIcons.Application,Text="随手译",Visible=true};tray.MouseDown+=(_,_)=>source=NativeMethods.GetForegroundWindow();tray.DoubleClick+=(_,_)=>Start(TaskMode.Translation,source);UpdateMenu();
  var conflicts=new List<string>();if(!hotkeys.Register(1,settings.TranslationModifiers,settings.TranslationKey))conflicts.Add("翻译");if(!hotkeys.Register(2,settings.ExplanationModifiers,settings.ExplanationKey))conflicts.Add("解释");if(conflicts.Count>0)tray.ShowBalloonTip(7000,"快捷键冲突",string.Join('、',conflicts)+"快捷键被占用，请在设置修改；托盘菜单仍可使用。",ToolTipIcon.Warning);
  Application.Idle+=Initialize;
 }
 async void Initialize(object? sender,EventArgs e){Application.Idle-=Initialize;try{foreach(var path in DependencyInstaller.Candidates(Path.Combine(data,"Dependencies","CodeBuddy","2.164.0","codebuddy.exe")))if(await DependencyInstaller.CompatibleAsync(path,Work,CancellationToken.None)){cli=path;break;}if(cli is null||!settings.SetupCompleted){ShowSetup();return;}await RefreshModels(false);}catch(Exception ex){tray.ShowBalloonTip(5000,"请完成首次使用",ex.Message,ToolTipIcon.Warning);ShowSetup();}}
 void UpdateMenu(){var menu=new ContextMenuStrip();menu.Items.Add("翻译",null,(_,_)=>Start(TaskMode.Translation,source));menu.Items.Add("解释",null,(_,_)=>Start(TaskMode.Explanation,source));var submenu=new ToolStripMenuItem("AI 模型（当前："+settings.SelectedModelId+"）");foreach(var model in models.Append(settings.SelectedModelId).Distinct()){var item=new ToolStripMenuItem(model+(models.Contains(model)?"":"（需确认）")){Checked=model==settings.SelectedModelId};item.Click+=(_,_)=>SetModel(model);submenu.DropDownItems.Add(item);}submenu.DropDownItems.Add("刷新模型列表",null,async(_,_)=>await RefreshModels(true));submenu.DropDownItems.Add("恢复 hy3",null,(_,_)=>SetModel("hy3"));menu.Items.Add(submenu);menu.Items.Add("设置",null,(_,_)=>ShowSettings());menu.Items.Add("首次使用 / 本人登录",null,(_,_)=>ShowSetup());menu.Items.Add("退出",null,(_,_)=>ExitThread());var old=tray.ContextMenuStrip;tray.ContextMenuStrip=menu;old?.Dispose();}
 async Task RefreshModels(bool refresh){if(cli is null)return;try{models=await ModelCatalog.LoadAsync(cli,Cache,Work,refresh,CancellationToken.None);UpdateMenu();}catch(Exception ex){UpdateMenu();if(refresh)MessageBox.Show(ex.Message+" 已保留上次列表及您的选择。");}}
 void SetModel(string id){settings.SelectedModelId=id;settings.Save(SettingsPath);result?.UpdateModel(id);settingsWindow?.UpdateModel(id);UpdateMenu();}
 void SetTheme(string id){settings.ThemeId=id;settings.Save(SettingsPath);result?.ApplyTheme(id);if(feedback is {IsDisposed:false})Theme.Get(id).Apply(feedback);}
 void ShowSettings(){if(settingsWindow is {IsDisposed:false}){settingsWindow.Activate();return;}settingsWindow=new(settings,models,SetModel,SetTheme,ChangeHotkeys,async()=>{await RefreshModels(true);settingsWindow?.Close();ShowSettings();},value=>{settings.ParallelGeneration=value;settings.Save(SettingsPath);});settingsWindow.Show();}
 bool ChangeHotkeys(int a,uint am,int b,uint bm){hotkeys.Unregister(1);hotkeys.Unregister(2);if(hotkeys.Register(1,am,a)&&hotkeys.Register(2,bm,b)){settings.TranslationKey=a;settings.TranslationModifiers=am;settings.ExplanationKey=b;settings.ExplanationModifiers=bm;settings.Save(SettingsPath);return true;}hotkeys.Unregister(1);hotkeys.Unregister(2);hotkeys.Register(1,settings.TranslationModifiers,settings.TranslationKey);hotkeys.Register(2,settings.ExplanationModifiers,settings.ExplanationKey);return false;}
 void ShowSetup(){if(setup is {IsDisposed:false}){setup.Activate();return;}setup=new(data,settings.SelectedModelId,settings.ThemeId);setup.Ready+=path=>{cli=path;settings.SetupCompleted=true;settings.Save(SettingsPath);tray.ShowBalloonTip(6000,"随手译已就绪","选中文字后按 Ctrl+Shift+F8 翻译、Ctrl+Shift+F9 解释；无选择时框选截图。",ToolTipIcon.Info);};setup.Show();}
 void ShowBusy(){if(captureWindow is {IsDisposed:false}){captureWindow.BringToFront();return;}if(feedback is {IsDisposed:false}){feedback.Show();feedback.BringToFront();return;}if(result is {IsDisposed:false}){result.Show();result.BringToFront();return;}tray.ShowBalloonTip(3000,"正在结束当前任务","清理完成后可以重新使用。",ToolTipIcon.Info);}
 void CancelGeneration(){revision++;request?.Cancel();var owner=request;request=null;var pending=operations.Values.ToArray();operations.Clear();requestModels.Clear();if(owner is not null)_=DisposeAfter(pending,owner);}
 static async Task DisposeAfter(Task[] pending,CancellationTokenSource owner){try{await Task.WhenAll(pending);}catch(Exception){}finally{owner.Dispose();}}
 void CancelPanel(ResultWindow panel){var pending=operations.Where(p=>!p.Value.IsCompleted).Select(p=>p.Key).ToArray();CancelGeneration();foreach(var mode in pending)panel.ShowError("已取消。可以重试或切换模式。",mode:mode);}
 async void Start(TaskMode mode,IntPtr window){if(busy||(operations.Values.Any(t=>!t.IsCompleted)&&result is {IsDisposed:false}&&!result.HasResult(TaskMode.Translation)&&!result.HasResult(TaskMode.Explanation))){ShowBusy();return;}if(cli is null||!settings.SetupCompleted){ShowSetup();return;}var previous=result;if(previous is {IsDisposed:false})CancelPanel(previous);else CancelGeneration();busy=true;request=new();var token=request.Token;var model=settings.SelectedModelId;var both=settings.ParallelGeneration;bool created=false;previous?.Hide();feedback=new(settings.ThemeId);feedback.CancelRequested+=()=>request?.Cancel();feedback.SetStatus("正在读取选中文字…");feedback.Show();
  try {var selection=SelectionReader.ReadAsync(window,token);activeOperation=selection;var text=await selection;if(string.IsNullOrWhiteSpace(text)){feedback.Finish();feedback=null;await Task.Delay(120,token);using var capture=new CaptureOverlay();captureWindow=capture;using var cancel=token.Register(()=>capture.BeginInvoke(capture.Close));if(capture.ShowDialog()!=DialogResult.OK||capture.CapturedImage is null)return;captureWindow=null;using var image=capture.CapturedImage;feedback=new(settings.ThemeId);feedback.CancelRequested+=()=>request?.Cancel();feedback.SetStatus("正在识别框选区域的中英文…");feedback.Show();var recognition=OcrService.RecognizeAsync(image,token);activeOperation=recognition;text=await recognition;}token.ThrowIfCancellationRequested();if(string.IsNullOrWhiteSpace(text)){MessageBox.Show("没有识别到文字，请缩小范围或重新框选。");return;}
   feedback?.Finish();feedback=null;result=null;previous?.Close();var panel=new ResultWindow(text,mode,models,model,settings.ThemeId);result=panel;created=true;panel.FormClosed+=(_,_)=>{if(result==panel)CancelGeneration();};panel.CancelRequested+=()=>CancelPanel(panel);panel.ModeRequested+=next=>RunMode(panel,next);panel.RetryRequested+=()=>RunMode(panel,panel.Mode,true);panel.ModelSelected+=SetModel;panel.LoginRequested+=ShowSetup;panel.ModelsRequested+=ShowSettings;panel.Show();Launch(panel,mode,model);if(both)Launch(panel,mode==TaskMode.Translation?TaskMode.Explanation:TaskMode.Translation,model);
  }catch(OperationCanceledException){if(created&&result is {IsDisposed:false})result.ShowError("已取消。可以重试或切换模式。");}catch(Exception ex){if(created&&result is {IsDisposed:false})result.ShowError(ex.Message,(ex as AIException)?.Kind);else MessageBox.Show(ex.Message);}finally{captureWindow=null;feedback?.Finish();feedback=null;if(!created&&previous is {IsDisposed:false})previous.Show();if(!created&&previous is null)CancelGeneration();busy=false;}
 }
 void RunMode(ResultWindow panel,TaskMode mode,bool retry=false){if(busy){ShowBusy();return;}if(panel.IsDisposed)return;if(operations.TryGetValue(mode,out var pending)&&!pending.IsCompleted){panel.ShowLoading(requestModels[mode]);return;}if(!retry&&panel.HasResult(mode))return;Launch(panel,mode,settings.SelectedModelId);}
 void Launch(ResultWindow panel,TaskMode mode,string model){if(request is null||request.IsCancellationRequested){CancelGeneration();request=new();}requestModels[mode]=model;if(panel.Mode==mode)panel.ShowLoading(model);operations[mode]=RunRequest(panel,mode,model,request.Token,revision);}
 async Task RunRequest(ResultWindow panel,TaskMode mode,string model,CancellationToken token,int version){try{var response=await new CodeBuddyClient(cli!,Work).ProcessAsync(panel.OriginalText,mode,model,token);if(result==panel&&!panel.IsDisposed&&!token.IsCancellationRequested&&revision==version)panel.ShowResult(response);}catch(OperationCanceledException){if(result==panel&&!panel.IsDisposed&&revision==version)panel.ShowError("已取消。可以重试或切换模式。",mode:mode);}catch(Exception ex){if(result==panel&&!panel.IsDisposed&&revision==version)panel.ShowError(ex.Message,(ex as AIException)?.Kind,mode);}}
 protected override async void ExitThreadCore(){request?.Cancel();try{await Task.WhenAll(operations.Values.ToArray());}catch(Exception){}if(activeOperation is not null)try{await activeOperation;}catch(Exception){}feedback?.Finish();captureWindow?.Close();result?.Close();setup?.Close();settingsWindow?.Close();hotkeys.Dispose();tray.Visible=false;tray.Dispose();shutdownWait?.Unregister(null);shutdown.Dispose();dispatcher.Dispose();base.ExitThreadCore();}
}
